B.bpj=new A.dh("\ud558\uc740\uc740 \ubaa8\ub450\uc5d0\uac8c \uc218\uac74\uc744 \ub098\ub220 \uc8fc\uba74\uc11c\ub3c4 \ud50c\ub808\uc774\uc5b4 \ubaab\uc740 \uac00\uae4c\uc6b4 \uc758\uc790\uc5d0 \uc870\uc6a9\ud788 \ub450\uc5c8\ub2e4.","\ub124\uac00 \ub3c4\uc6c0\ubc1b\ub294 \uac8c \ubd88\ud3b8\ud560 \uc218\ub3c4 \uc788\uc73c\ub2c8\uae4c \uc5ec\uae30 \ub458\uac8c. \uac00\uc838\uac08\uc9c0\ub294 \ub124\uac00 \uc815\ud574.","\uc6b0\ub9ac \uac08\ub4f1\uc744 \uc624\ub298 \uc5b5\uc9c0\ub85c \ud480 \uc0dd\uac01\uc740 \uc5c6\uc5b4. \uc784\ucc28\uc778 \ub9d0\ub9cc \ub04a\uc9c0 \uc54a\uace0 \ub4e3\uc790.","\ub124 \ub9c8\uc74c\uae4c\uc9c0 \ub0b4\uac00 \uc815\ud558\uc9c0 \uc54a\uc73c\ub824\uace0 \ud588\uc5b4.")
B.bpw=new A.dh("\ud558\uc740\uc740 \ub9d0\uc744 \uace0\ub974\ub290\ub77c \ud3c9\uc18c\ubcf4\ub2e4 \uc9c8\ubb38 \uc0ac\uc774\uac00 \uae38\uc5c8\ub2e4.","\ub0b4\uac00 \ub610 \uad1c\ucc2e\uc544\uc9c0\ub77c\uace0 \uc7ac\ucd09\ud560\uae4c \ubd10 \uba3c\uc800 \ubb3c\uc744\uac8c. \uac19\uc774 \ub4e4\uc5b4\ub3c4 \uad1c\ucc2e\uc544?","\uc2eb\uc73c\uba74 \ub0b4\uac00 \ud63c\uc790 \ub4e3\uace0 \uadf8\ub300\ub85c \uc804\ud560\uac8c. \uc608\uc058\uac8c \ubc14\uafd4 \ub9d0\ud558\uc9c0 \uc54a\uace0.","\ub124\uac00 \uc2eb\ub2e4\uace0 \ud55c \ubd80\ubd84\uc740 \uadf8\ub300\ub85c \ub0a8\uacbc\uc5b4.")
B.bpC=new A.dh("\ud558\uc740\uc740 \uc6b0\uc0b0 \ub450 \uac1c \uc911 \ud558\ub098\ub97c \ub0b4\ubc00\ub2e4 \uc7a0\uae50 \uba48\ucdc4\ub2e4.","\uac19\uc774 \uc4f8\ub798? \uc544\ub2c8\uba74 \ud558\ub098\uc529 \ub4e4\uae4c? \ub124\uac00 \ud3b8\ud55c \ucabd\uc73c\ub85c.","\uc218\ub9ac\ubd80\ud130 \ub9d0\ud558\uae30 \uc804\uc5d0 \uc784\ucc28\uc778\ud55c\ud14c \ubb50\uac00 \uc81c\uc77c \uae09\ud55c\uc9c0 \ubb3c\uc5b4\ubcf4\uc790.","\uba3c\uc800 \ubb3c\uc5b4\ubcf4\ub2c8\uae4c \ub0b4\uac00 \uc9d0\uc791\ud55c \uac70\ub791 \ub2e4\ub978 \uac8c \uc788\uc5c8\uc5b4.")
B.bpx=new A.dh("\ud558\uc740\uc774 \uc816\uc740 \uc218\uac74\uc744 \ubc1b\uc544 \ub4e4\uace0 \ud50c\ub808\uc774\uc5b4 \uc0c1\ud0dc\ubd80\ud130 \uc0b4\ud3c8\ub2e4.","\ub108 \uc190 \ucc28\uac00\uc6cc. \uad1c\ucc2e\uc544? \uadf8\ub0e5 \uc218\uac74\ub9cc \uc904\uae4c, \uc7a0\uae50 \uc274\ub798?","\uc784\ucc28\uc778\ub3c4 \ub611\uac19\uc744 \uac70\uc57c. \uc6b0\ub9ac\uac00 \ud574 \uc904 \ub9d0 \ub9d0\uace0, \uc6d0\ud558\ub294 \uac78 \uba3c\uc800 \ub4e3\uc790.","\ub124\uac00 \uba3c\uc800 \uae30\ub2e4\ub824 \uc918\uc11c \uadf8\ubd84\ub3c4 \ub05d\uae4c\uc9c0 \ub9d0\ud588\uc5b4.")
B.bpI=new A.dh("\ud558\uc740\uc740 \uc816\uc740 \uba38\ub9ac\uce74\ub77d\uc744 \ud138\ub2e4\uac00 \ucc98\uc74c\uc73c\ub85c \uc790\uae30 \ud53c\uace4\ud55c \uc5bc\uad74\uc744 \uc228\uae30\uc9c0 \uc54a\uc558\ub2e4.","\ub098 \uc0ac\uc2e4 \uc880 \ubc85\ucc28. \ub2e4 \ucc59\uae30\ub824\ub2e4\uac00 \ub204\uad6c \ub9d0\ub3c4 \uc81c\ub300\ub85c \ubabb \ub4e4\uc744\uae4c \ubd10.","\uc624\ub298\uc740 \ub0b4 \uc606\uc5d0\uc11c \uac19\uc774 \ub4e4\uc5b4 \uc904\ub798? \ud574\uacb0\uc740 \uadf8\ub2e4\uc74c\uc5d0 \ud574\ub3c4 \ub418\ub2c8\uae4c.","\ub0b4\uac00 \ud798\ub4e4\ub2e4\uace0 \uba3c\uc800 \ub9d0\ud574\ub3c4 \ub124\uac00 \ubd80\ub2f4\uc2a4\ub7ec\uc6cc\ud558\uc9c0 \uc54a\uc544\uc11c \ub2e4\ud589\uc774\uc5c8\uc5b4.")
B.bjQ=new A.ce([B.f9,B.bpj,B.el,B.bpw,B.d3,B.bpC,B.fa,B.bpx,B.fb,B.bpI],t.XH)
B.bq4=new A.f9("ask_tenant_first","\uc784\ucc28\uc778\uc774 \uc6d0\ud558\ub294 \ub3c4\uc6c0\ubd80\ud130 \ubb3b\ub294\ub2e4","\uc88b\uc740 \uc758\ub3c4\ub85c \ud574\uacb0\ucc45\uc744 \uba3c\uc800 \uc815\ud558\uc9c0 \uc54a\ub294\ub2e4.","\uc751. \uc6b0\ub9ac\uac00 \uc0dd\uac01\ud55c \uae09\ud55c \uc77c\uacfc \uadf8\ubd84\uc774 \ub9d0\ud55c \uae09\ud55c \uc77c\uc774 \ub2ec\ub790\uc5b4.",1,1,1,0)
B.bq7=new A.f9("separate_people_and_cost","\uc601\uc5c5 \uc190\uc2e4\uacfc \uc218\ub9ac\ube44\ub97c \ud568\uaed8 \uc801\ub294\ub2e4","\uc0ac\ub78c\uc758 \uc2dc\uac04\uc744 \ud68c\uacc4 \ubc16\uc73c\ub85c \uc9c0\uc6b0\uc9c0 \uc54a\ub294\ub2e4.","\uc22b\uc790\ub85c \uc801\uc5b4 \ub450\ub2c8\uae4c \ubbf8\uc548\ud558\ub2e4\ub294 \ub9d0\ub9cc \ud558\uace0 \ub05d\ub0b4\uc9c0 \uc54a\uac8c \ub3fc.",0,0,0,2)
B.bqg=new A.f9("offer_choice","\ud568\uaed8\ud560\uc9c0 \uac01\uc790 \uc6c0\uc9c1\uc77c\uc9c0 \ud558\uc740\uc5d0\uac8c \ubb3b\ub294\ub2e4","\ub3c4\uc6c0\uc744 \uac15\uc694\ud558\uc9c0 \uc54a\uace0 \uc120\ud0dd\uad8c\uc744 \ub3cc\ub824\uc900\ub2e4.","\uace0\ub9c8\uc6cc. \uc624\ub298\uc740 \uac19\uc774 \ub4e3\uace0, \uc815\ub9ac\ub294 \ub0b4\uac00 \ud574 \ubcfc\uac8c.",0,1,0,0)
B.b9W=s([B.bq4,B.bq7,B.bqg],t.vg)
B.bq1=new A.ob("2000-07-property-operation",7,"park_haeun","7\uc6d4 \xb7 \ube44 \uc624\ub294 \ub0a0\uc758 \ube48 \ubc29","\uad50\uc721\uc6a9 \uc0c1\uac00 \xb7 \ube57\ubb3c \uc0c8\ub294 \ubcf5\ub3c4","\uc7a5\ub9db\ube44\uc5d0 \uad50\uc721\uc6a9 \uc810\ud3ec \ucc9c\uc7a5\uc5d0\uc11c \ubb3c\uc774 \uc0dc\ub2e4. \uc218\ub9ac \uc21c\uc11c\ub9cc\uc774 \uc544\ub2c8\ub77c \uc784\ucc28\uc778\uc774 \uc6d0\ud558\ub294 \uc124\uba85\uacfc \uae30\ub2e4\ub9b4 \uc218 \uc788\ub294 \uc2dc\uac04\uc744 \ud655\uc778\ud574\uc57c \ud55c\ub2e4.","\ubd80\ub3d9\uc0b0 \xb7 \uc218\ub9ac\xb7\ubcf4\ud5d8\xb7\uc784\ucc28\uc778 \uc6b4\uc601 \ud574\uae08","\uc11c\ud558\ub298: \uc218\ub9ac\ube44\ub9cc \uacc4\uc0b0\ud558\uba74 \uc808\ubc18\uc774\uc5d0\uc694. \uadf8\ub3d9\uc548 \uc7a5\uc0ac\ub97c \ubabb \ud558\ub294 \uc0ac\ub78c\uc758 \uc2dc\uac04\ub3c4 \uacc4\uc57d\uc5d0 \ub0a8\uc2b5\ub2c8\ub2e4.",B.bix,B.bjQ,B.b9W)
