B.a7w=new A.ly("kim_seoa","\uae40\uc11c\uc544",1987,2,12,"\ud504\ub85c\uc81d\ud2b8 \ub370\uc2dc\uba40 \xb7 \ucd5c\uc885 10\uc778","ISFJ","\uc2e0\ub8b0 \uae30\ub85d \xb7 \uc5ed\ubc1c\uc0c1 \uac00\uce58 \ub2f4\ub2f9","\uae30\ub85d\uc73c\ub85c \uc57d\uc18d\uacfc \uc0ac\ub78c \uc0ac\uc774\uc758 \uc2e0\ub8b0\ub97c \uc9c0\ud0a4\ub294 \ucc28\ubd84\ud55c \uc0dd\ud65c\uc2e4 \uc11c\uae30.","\ub9d0\uc218\ub294 \ub9ce\uc9c0 \uc54a\uc9c0\ub9cc \uce5c\uad6c\uac00 \ube4c\ub9b0 \ubb3c\uac74\uacfc \uc2eb\uc5b4\ud558\ub294 \uac83\uae4c\uc9c0 \uc138\uc2ec\ud558\uac8c \uae30\uc5b5\ud55c\ub2e4. \uaddc\uce59\uc744 \uc88b\uc544\ud574\ub3c4 \uad8c\uc704\uc5d0 \ubb34\uc870\uac74 \ub530\ub974\uc9c0\ub294 \uc54a\uc73c\uba70, \uae30\ub85d\uc774 \uc0ac\ub78c\uc744 \ub35c \uc0c1\ud558\uac8c \ub9cc\ub4dc\ub294\uc9c0 \uba3c\uc800 \ubcf8\ub2e4.","\uc815\ub3c8\ub41c \uc7a5\ubd80, \uc0c9\uc0c9\uc758 \ud544\uae30\uad6c, \uc57d\uc18d\uc774 \uc815\ud655\ud788 \uc9c0\ucf1c\uc9c0\ub294 \uc21c\uac04","\ud769\uc5b4\uc9c4 \uc57d\uc18d\uacfc \uc0dd\ud65c \uc815\ubcf4\ub97c \ube60\ub728\ub9ac\uc9c0 \uc54a\uace0 \ud55c \uc7a5\uc758 \uae30\ub85d\uc73c\ub85c \ubb36\ub294\ub2e4.","\uafb8\uc900\ud55c \uc6b4\uc601 \uae30\ub85d\uacfc \uc2e0\ub8b0\uac00 \uc2e4\uc81c \uc22b\uc790\ub85c \uc774\uc5b4\uc9c0\ub294 \ud68c\uc0ac\ub97c \uc120\ud638\ud55c\ub2e4.","\uc791\uc740 \ubc30\ub824\uc640 \ubc18\ubcf5\ud574\uc11c \uc9c0\ucf1c\uc9c4 \uc57d\uc18d\uc744 \uc624\ub798 \uae30\uc5b5\ud558\uba70 \ucc9c\ucc9c\ud788 \ub9c8\uc74c\uc744 \uc5f0\ub2e4.",B.bcM,4294151062,u.hg)
